{  
  "counterarguments": [  
    {  
      "claim": "آسیب‌پذیری بدون قضاوت شرایط مناسب می‌تواند منجر به سوءاستفاده عاطفی شود، زیرا نه همه افراد آمادهٔ پذیرش یا پاسخگویی مسئولانه به احساسات عمیق دیگران هستند.",  
      "severity": "high",  
      "kind": "contextual limitation"  
    },  
    {  
      "claim": "در فرهنگ‌ها یا زمینه‌های اجتماعی خاص، آسیب‌پذیری اغلب به عنوان نشانه‌ای از ناامنی یا نابالغی تفسیر می‌شود، که می‌تواند منجر به کاهش احترام یا قدرت رابطه‌ای شود.",  
      "severity": "medium",  
      "kind": "cultural relativism"  
    },  
    {  
      "claim": "شجاعت باید با خرد همراه باشد؛ آسیب‌پذیری بی‌ملاحظه — مثلاً در مراحل اولیه رابطه یا در حضور افراد ناپایدار از نظر عاطفی — ممکن است بیشتر نشانهٔ بی‌پروایی باشد تا شجاعت واقعی.",  
      "severity": "high",  
      "kind": "epistemic caution"  
    },  
    {  
      "claim": "در برخی روابط، مانند روابط کاری یا سلسله‌مراتبی، آسیب‌پذیری مفرط می‌تواند مرزهای حرفه‌ای را تضعیف کند و عملکرد یا اعتماد را به جای تقویت، تضعیف کند.",  
      "severity": "medium",  
      "kind": "domain incompatibility"  
    }  
  ]  
}
